handleTokenUsageUpdated(params) {
  /* agenta:turn-usage */ {
    const usage = params.tokenUsage;
    const state = this.sessionState;
    const keys = ["totalTokens", "inputTokens", "cachedInputTokens", "outputTokens", "reasoningOutputTokens"];
    if (state.lastTokenUsage == null) {
      state.agentaTurnBase = Object.fromEntries(keys.map((k) => [k, (usage.total?.[k] ?? 0) - (usage.last?.[k] ?? 0)]));
    }
    state.agentaTurnTokenUsage = toTokenCount(Object.fromEntries(keys.map((k) => [k, Math.max(0, (usage.total?.[k] ?? 0) - (state.agentaTurnBase?.[k] ?? 0))])));
  }
  this.sessionState.lastTokenUsage = toTokenCount(params.tokenUsage.last);

sessionState.currentTurnId = null;
sessionState.lastTokenUsage = null;
sessionState.agentaTurnTokenUsage = null;
